formulas.expression:
IF(
  {!productosFacturaSucursal.outputSelectedRow.Unidad_de_Medida__c} = "KG",

  /* Cálculo cuando es KG */
  IF(
    {!productosFacturaSucursal.outputSelectedRow.Peso_neto__c} > 0,
    ROUND(
      {!Cantidad_Reclamada_sucursal} *
      (
        {!productosFacturaSucursal.outputSelectedRow.Total_con_Rapel__c} /
        {!productosFacturaSucursal.outputSelectedRow.Peso_neto__c}
      ),
      0
    ),
    0
  ),

  /* Cálculo cuando NO es KG */
  IF(
    {!productosFacturaSucursal.outputSelectedRow.Cantidad__c} > 0,
    ROUND(
      {!Cantidad_Reclamada_1_sucursal} *
      (
        {!productosFacturaSucursal.outputSelectedRow.Total_con_Rapel__c} /
        {!productosFacturaSucursal.outputSelectedRow.Cantidad__c}
      ),
      0
    ),
    0
  )
)
